ALTER TABLE "telrad"."tenants" ADD COLUMN "film_export_tariff_paise" integer NOT NULL DEFAULT 50000;

CREATE TABLE "telrad"."film_exports" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer REFERENCES "telrad"."tenants"("id"),
  "study_id" integer NOT NULL REFERENCES "telrad"."studies"("id"),
  "invoice_line_id" integer REFERENCES "telrad"."invoice_lines"("id"),
  "medium" text NOT NULL,
  "quantity" smallint NOT NULL DEFAULT 1,
  "unit_paise" integer NOT NULL,
  "total_paise" integer NOT NULL,
  "requested_by_user_id" integer REFERENCES "telrad"."users"("id"),
  "requested_by_name" text NOT NULL,
  "patient_name" text,
  "study_description" text,
  "exported_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE INDEX "film_exports_tenant_idx" ON "telrad"."film_exports" ("tenant_id", "exported_at");
